// Room "P0 east bedroom" (interior designer's part): box x 11..12, y 6..8, z 14..20 (2 wide, 7 deep).
// Two white beds (bed() halves): bed A's head on the partition at x 10 (z 14), bed B's head on the south wall (z 20).
// The east wall is window (z 14..15, 19..20) and solid at z 16..18, so no bed can take the east wall without
// blocking the door lane at z 16. The lane runs down x 11 from the doorway (10,6..7,16) to the south end.
// Chest and barrel dresser on the east wall at z 16..17, a flower pot on the barrel. Lanterns hang under the ceiling.
import { bed, layers, B } from "/Volumes/ext1/swe/repos/minecraft-design/tools/src/build.mjs";

export function build(g) {
  // the beds: foot, then the head one step toward facing (the pillow end on a solid wall)
  bed(g, [12, 6, 14], "west", "white");
  bed(g, [12, 6, 19], "south", "white");

  // dresser: a chest (lid toward the room) and a barrel, on the east wall, at feet level y 6
  layers(g, [11, 6, 14], {
    c: ["chest", { facing: "west", type: "single" }],
    b: ["barrel", { facing: "up", open: "false" }],
  }, [
    ["..", "..", ".c", ".b", "..", "..", ".."],
  ]);

  // a potted flower on the barrel top (y 7); nothing on the lane
  layers(g, [11, 7, 14], {
    p: ["potted_poppy", {}],
  }, [
    ["..", "..", "..", ".p", "..", "..", ".."],
  ]);

  // hanging lanterns under the ceiling (the block above at y 9 is the storey's ceiling)
  g.set(12, 8, 15, ...B.lantern(true));
  g.set(11, 8, 19, ...B.lantern(true));
  return {};
}

